{
  "schema": "stellar-forge.opportunity-response-workbook.v1",
  "title": "MCC Software Development Recompete: response working draft",
  "opportunityReference": "95332427K0001",
  "seed": {
    "path": "references/operator-seed.json",
    "gitBlob": "5934cfa6108e7ad61bc17bb74611df8bd8cf6229",
    "sha256": "d5bcae2868ab7220a2c822bbf065786dba6862dea0bbb83732e19bd75f22b49e"
  },
  "authoringBasis": "Authored engineering recommendations and company-evidence work orders against the exact retained MCC RFI/PWS. The response field is working material; a row marked unanswered remains a preparation task until its company evidence or explicit N/A disposition is reviewed.",
  "ownerSemantics": "Owner labels propose the accountable functional role. The company assigns the actual person and accepts the role through its working review.",
  "sourceBindings": [
    {
      "key": "mcc-rfi",
      "filename": "mcc-rfi-government-text.txt",
      "sha256": "a056f3412429ae69c389def65021d15eac4bed29df962cfdb91c91b9bdd2aa73",
      "bytes": 11184,
      "url": "https://govtribe.com/file/government-file/request-for-information-rfi-final-dot-docx"
    },
    {
      "key": "mcc-pws",
      "filename": "mcc-pws-government-text.txt",
      "sha256": "c517b8df490e686da248c751b094fae9083bd46722e2f6fbb5484ccbe8cb908e",
      "bytes": 52325,
      "url": "https://govtribe.com/file/government-file/performance-work-statement-pws-final-dot-docx"
    },
    {
      "key": "mcc-event",
      "filename": "mcc-industry-day-excerpt.txt",
      "sha256": "79d600d186d7c45d9941af6d02470ec014903c292533039fc3df23d7603fdca9",
      "bytes": 2016,
      "url": "https://govtribe.com/file/government-file/rfi-notice-of-intent-dot-docx"
    },
    {
      "key": "mcc-notice",
      "filename": "mcc-notice-record.json",
      "sha256": "600c4082662047a72bb83dfd48ddf6478f11f5d31eef8894adbb6a11653b9b14",
      "bytes": 2196,
      "url": "https://sam.gov/workspace/contract/opp/ec4254f4fdf24f8998bd4e10d5b58050/view"
    },
    {
      "key": "lgndx-company",
      "filename": "lgndx-company-evidence.json",
      "sha256": "bdbb1ce9861b04395d43e00b4ceba23252a45b36933ddbd379ad2221f5a40092",
      "bytes": 4313,
      "url": "https://lgndx.com/product/apollo-evo"
    },
    {
      "key": "funded-prime-capture",
      "filename": "funded-prime-capture.json",
      "sha256": "c07abc56456e888407e561ac8b50906ce1f7884bcc6835fdfdb05fffb949f045",
      "bytes": 1453,
      "url": "https://api.usaspending.gov/api/v2/search/spending_by_award/"
    },
    {
      "key": "funded-prime-response",
      "filename": "funded-prime-response.json",
      "sha256": "c0c74c897b95db8657cfe9bd3c1b76526f5ff057ad2966d6f4a0f98c06cd9319",
      "bytes": 30030,
      "url": "https://api.usaspending.gov/api/v2/search/spending_by_award/"
    }
  ],
  "responseRules": {
    "maxPages": 20,
    "capabilityMaxPages": 1,
    "excludedSections": [
      "cover page",
      "table of contents"
    ],
    "numbering": "Retain the original RFI number for every answer or explicit N/A.",
    "deployedAiRule": "Question 6 requires sourced operational deployments; questions 6.a and 6.b retain their separate company-structure and proposed-method scopes.",
    "pagination": "Review the actual final formatted response and one-page capability statement; the workbook does not infer page counts from word counts."
  },
  "rows": [
    {
      "number": "1",
      "decision": "gap",
      "owner": "Company capture lead",
      "response": "Prepare the response header from company-approved records: legal entity name; complete business address; telephone; named response owner and direct contact information; UEI; and the company size representation applicable to the recommended NAICS. Compare a custom application engineering classification with the broader integration, administration and O&M scope before recommending one code. The retained award record identifies NAICS 541511 for that award; use it as a research lead when the company reviews this procurement’s predominant purpose. Ask the company contracts owner to approve the final code, applicable size standard and representation, then retain the approval as a new source.",
      "reviewNote": "RFI 1, government text L60. The seed supplies the published company name, website and award UEI, but lacks an approved response contact, full address, telephone and current size representation. Assign the actual company response owner and retain the relevant company/SAM representation before turning this row into a substantive answer. Keep the original award NAICS separate from the procurement recommendation.",
      "responseDisposition": "unanswered",
      "status": "open",
      "issuedEvidence": [
        {
          "sourceKey": "mcc-issued-rfi-text",
          "locator": "word/document.xml B014; RFI question 1",
          "excerpt": "Please provide your company name, address, telephone number, point of contact name (including contact information), and company size. What NAICS code do you recommend for this procurement and what is your company size standard under this NAICS code?"
        }
      ]
    },
    {
      "number": "2",
      "decision": "partial",
      "owner": "Capture lead and solution architect",
      "response": "Proposed questions for MCC: (1) provide the Appendix B application and technology inventory referenced by PWS 2.2 and 4.2.1.1, with dependencies, data classifications, support tiers, usage and available incident/change history; (2) reconcile RFI 5.c's reference to Section 5.0 deliverables with the issued PWS's Section 5.0 Labor Requirements, identify the applicable deliverable/acceptance schedule and Section H key-personnel designations, and reconcile the Scope paragraph's Section 4.4 Infrastructure reference with the issued Section 4.4 Application Administration; (3) identify each application's development, test, staging and production owner, approval path and access lead times; (4) provide the current pipeline tools, infrastructure interfaces, patch windows, restore objectives and operational acceptance criteria; (5) define service hours, on-call expectations and severity-based targets in addition to the stated Eastern core hours; (6) specify the backlog, expected enhancement volume and boundary between recurring O&M and separately ordered surge work; and (7) clarify modernization budget, platform/license constraints, data migration responsibilities and acceptance authority. The acquired October 6 resource index contains the RFI, PWS and Industry Day notice; the referenced Appendix B and Section H are not included in that three-file packet.",
      "reviewNote": "Proposed market-research feedback for company selection. The original SAM RFI/PWS files confirm the existing questions and cross-reference issues. Appendix B and Section H remain requests for the actual referenced material. Actual issuer answers should be retained as question_response sources.",
      "responseDisposition": "answer",
      "status": "in_progress",
      "issuedEvidence": [
        {
          "sourceKey": "mcc-issued-rfi-text",
          "locator": "word/document.xml B015; RFI question 2",
          "excerpt": "Please share any questions or feedback on the draft performance work statement or MCC’s IT Environment. This feedback will be utilized to refine and enhance the final Request for Proposal (RFP). Is there any additional information that your company would require in order to submit a competitive proposal in response to the eventual solicitation?"
        },
        {
          "sourceKey": "mcc-issued-pws-text",
          "locator": "word/document.xml B044; PWS 1.0",
          "excerpt": "See Section 4.1 for specific tasks related to Contract Program Management, Architecture, and Security; Section 4.2 for Operations, Maintenance, and Enhancements (OME); Section 4.3 for Surge Support and New Development; and Section 4.4 for Infrastructure."
        },
        {
          "sourceKey": "mcc-issued-pws-text",
          "locator": "word/document.xml B055; PWS 2.2",
          "excerpt": "An inventory of MCC’s current technical environment as related to the contract scope is available in Appendix B."
        },
        {
          "sourceKey": "mcc-issued-pws-text",
          "locator": "word/document.xml B153; PWS 4.2.1.1",
          "excerpt": "A complete listing of MCC’s applications and their supporting technologies can be found in Appendix B. MCC has several applications, most of which are written in C# with a .NET framework or are Power Platform-based applications. A smaller number of applications are written in PHP, Python, or are customized on platforms such as ServiceNow and Box.com. "
        },
        {
          "sourceKey": "mcc-issued-pws-text",
          "locator": "word/document.xml B320; PWS 5.0",
          "excerpt": "Labor Requirements"
        },
        {
          "sourceKey": "mcc-issued-pws-text",
          "locator": "word/document.xml B322; PWS 5.1",
          "excerpt": "Critical to performance of this Contract are the positions identified as key and the experience of the people in those positions. The proposed key positions as well as proposed staff shall show experience in the different skill sets necessary and the different functions to be performed. Key personnel required for this contract can be found in Section H of this solicitation."
        }
      ]
    },
    {
      "number": "3",
      "decision": "gap",
      "owner": "Contracts and teaming lead",
      "response": "Build a vehicle comparison sheet with separate rows for vehicles LGNDX actually holds and vehicles it recommends. For each held vehicle, obtain the master contract identifier, legal awardee and UEI, ordering period, relevant scope or category, ordering access and company-authorized point of contact. For each recommendation, assess whether the development, platform administration, O&M and surge services fit its scope; who can compete for orders; the pricing method; and whether an eligible teaming arrangement is needed. Ask the company to select a route after the Government’s contemplated BPA structure and ordering constraints are confirmed.",
      "reviewNote": "RFI 3, L62. Neither the published integration pages nor one reported federal award establish ownership of a government-wide acquisition contract. Retain the actual company contract/vehicle records and confirm current ordering eligibility. Any prospective vehicle-holder relationship remains a separately owned teaming decision with its own source.",
      "responseDisposition": "unanswered",
      "status": "open",
      "issuedEvidence": [
        {
          "sourceKey": "mcc-issued-rfi-text",
          "locator": "word/document.xml B016; RFI question 3",
          "excerpt": "Please provide a list of the government-wide acquisition contract vehicles that your company holds, and/or contracting vehicles that you would recommend for an IT acquisition of this scope."
        }
      ]
    },
    {
      "number": "4",
      "decision": "gap",
      "owner": "Past-performance lead",
      "response": "Prepare a one-page capability statement organized around MCC’s application engineering, Tier 3 support, platform administration, data integration and secure release responsibilities. Request two or three relevant Federal or multilateral engagements, each with client, contract or task identifier, actual company role, period, supported application/platform scope, operational responsibilities, accepted deliverables and an approved outcome statement. Select only the strongest source-supported examples for the one-page layout and keep the detailed reference records in the working package. Ask each engagement owner to approve client identification and reference-contact disclosure.",
      "reviewNote": "RFI 4, L64, imposes the one-page limit and comparable Federal and/or multilateral scope. The retained LGNDX award row establishes reported award fields; it does not establish the delivered functions, quality or client acceptance required for a capability statement. Keep the answer open until those performance records and company approvals are supplied.",
      "responseDisposition": "unanswered",
      "status": "open",
      "issuedEvidence": [
        {
          "sourceKey": "mcc-issued-rfi-text",
          "locator": "word/document.xml B017; RFI question 4",
          "excerpt": "Please provide a brief (not to exceed 1 page) capabilities statement detailing your company’s expertise and prior experience in providing IT support services similar in scope to MCC’s requirements to other Federal and/or multilateral clients."
        },
        {
          "sourceKey": "mcc-issued-pws-text",
          "locator": "word/document.xml B019; PWS 1.0",
          "excerpt": "The scope of this Performance Work Statement (PWS) is intended to cover Contractor support of all services required to provide application engineering, operations and maintenance (O&M) support, platform customization and configuration, and Tier 3 user support across all enterprise applications to support the information technology requirements of Millennium Challenge Corporation (MCC) Office of the Chief Information Officer (OCIO) Digital Services Team. The services to be acquired also include program management and administrative support necessary for the administration of this award. The following categories of activities are within the total scope of this Contract, and the contractor must have proven experience providing support for these activities within a federal agency:  "
        },
        {
          "sourceKey": "mcc-issued-pws-text",
          "locator": "word/document.xml B060; PWS 2.3",
          "excerpt": "To support this effort, the Contractor shall provide personnel with proven experience working on mature, highly agile product teams with deep expertise in application  engineering services including development, testing, business analysis, user interface design, and end-user support.  This includes teams that work on .NET/C# custom software development and configuration and customization of low-code platforms. "
        },
        {
          "sourceKey": "mcc-issued-pws-text",
          "locator": "word/document.xml B063; PWS 2.3",
          "excerpt": "Agile Software Development: One of MCC’s primary goals for this procurement is to enhance the agency’s IT platforms and applications with the delivery of frequent, high-quality releases. MCC requires contractors to demonstrate they utilize modern, agile scrum teams and culture in their current development work across the federal government and their approach to bringing this capability to MCC."
        },
        {
          "sourceKey": "mcc-issued-pws-text",
          "locator": "word/document.xml B065; PWS 2.3",
          "excerpt": "Experienced and Innovative: The Contractor selected should have experience in delivering innovative solutions to increase the effectiveness and efficiency of IT platforms within the federal government. "
        }
      ]
    },
    {
      "number": "5.a",
      "decision": "partial",
      "owner": "Delivery lead and contracts lead",
      "response": "Proposed structure: use a short discovery and transition work package to establish the application inventory, service boundaries, priority outcomes, measurable acceptance conditions and assumptions. Price well-defined delivery increments on a firm-fixed-price basis using demonstrable business outcomes, explicit interfaces, deployment responsibilities and a named Government acceptance owner. Keep each increment small enough to review as a complete usable capability. Reprioritize the uncommitted backlog at planned order or increment boundaries; a changed committed scope receives an impact statement and an agreed substitution or contract change. Price recurring O&M by an explicitly defined service envelope, with stated workload and support assumptions. Where investigation or emergency work cannot yet be specified reliably, propose a separately authorized, capped discovery or surge mechanism and convert subsequent defined delivery into fixed-price increments.",
      "reviewNote": "Proposed commercial and delivery design responding to RFI 5.a, L67–L68; the contracting officer would determine the permissible final vehicle and order structure. Review actual workload, data access, dependencies and acceptance timing before pricing. Distinguish the PWS’s 14-calendar-day surge plan response at L569 from authorization to begin work or a promise of staff deployment.",
      "responseDisposition": "answer",
      "status": "in_progress",
      "issuedEvidence": [
        {
          "sourceKey": "mcc-issued-rfi-text",
          "locator": "word/document.xml B019; RFI question 5.a",
          "excerpt": "MCC is evaluating opportunities to increase the use of firm-fixed-price (FFP) contracting for software development in alignment with recent Administration policy emphasizing greater use of fixed-price contracting where appropriate. Describe how your organization would recommend structuring a software development effort to maximize the appropriate use of FFP while maintaining the flexibility necessary to accommodate evolving requirements, technical uncertainty, and changing priorities. This can include hybrid FFP/T&M approaches. "
        },
        {
          "sourceKey": "mcc-issued-pws-text",
          "locator": "word/document.xml B058; PWS 2.3",
          "excerpt": "It is important to note that MCC requires flexibility to adjust to the agile IT environment and to support any new technologies or processes in line with evolving industry offerings, fluctuating budgetary availability, federal IT guidance, and new MCC business requirements. As a result, this award will allow the partnership between MCC and the Contractor to evolve over time, enabling continuous improvement and responsiveness to changes in the agency’s environment.  "
        },
        {
          "sourceKey": "mcc-issued-pws-text",
          "locator": "word/document.xml B067; PWS 2.3",
          "excerpt": "Cost Effective: MCC requires an award structure that allows flexible adjustment of service levels and support based upon changes in the federal budget and evolving agency priorities. The Contractor must be able to tailor service levels, provide modular options that can scale up or down as needed, and maintain a flexible environment that accommodates emerging technologies and shifting business needs.  MCC also seeks a partner capable of building and sustaining cloud-based applications while efficiently managing both operations and maintenance (O&M) and new feature development to achieve cost savings. "
        },
        {
          "sourceKey": "mcc-issued-pws-text",
          "locator": "word/document.xml B285; PWS 4.3.1",
          "excerpt": "New development work tasks issued by MCC are expected to be performed in accordance with industry best practices, NIST, OMB, and MCC policy and guidance in a consistent manner. Each new development task issued will include a SOW with a defined scope of work that is within the overall scope of the base contract. The Contractor shall provide a proposal with pricing that will be evaluated by MCC."
        },
        {
          "sourceKey": "mcc-issued-pws-text",
          "locator": "word/document.xml B302; PWS 4.3.1",
          "excerpt": "Required documents shall be identified in the new development task based on project tailoring to ensure a minimum set of documentation is produced that assists with maintenance, governance, and operations."
        }
      ]
    },
    {
      "number": "5.b",
      "decision": "gap",
      "owner": "Service management lead",
      "response": "Request a comparable operational engagement with the actual SLA schedule, measurement source, period of performance, service hours, incident priorities, exclusions, reporting owner and customer-approved results. Extract examples showing how incidents were detected and escalated, response and restoration were measured, planned maintenance was handled, and repeated faults drove a corrective change. Identify precisely which outcomes the company controlled and which depended on a separate hosting or security provider. Prepare a concise example table that links each claim to its retained contract, report or customer-approved account.",
      "reviewNote": "RFI 5.b, L69, asks for experience and examples. No comparable SLA history is present in the seed. Proposed targets can be discussed as recommendations elsewhere, but cannot fill this experience row. Obtain the actual service schedule and measured results, or have the company explicitly select N/A.",
      "responseDisposition": "unanswered",
      "status": "open",
      "issuedEvidence": [
        {
          "sourceKey": "mcc-issued-rfi-text",
          "locator": "word/document.xml B020; RFI question 5.b",
          "excerpt": "Do you have any experience working with SLAs for contracts similar in scope? Please provide examples."
        },
        {
          "sourceKey": "mcc-issued-pws-text",
          "locator": "word/document.xml B073; PWS 4.1.1",
          "excerpt": "The Contractor shall provide an Program Manager (PM) who will be responsible for the technical and functional activities required for the effective management of the entirety of this contract, including productivity and management tasks such as Project Management, Quality Assurance, and program level Change Management. An ideal PM is one who will focus on technical quality management, delivery and metric accountability, and act as a partner to MCC working collaboratively to achieve the contract goals."
        },
        {
          "sourceKey": "mcc-issued-pws-text",
          "locator": "word/document.xml B312; PWS 4.4.1",
          "excerpt": "The Contractor shall monitor and be responsible for the performance and operation of cloud-based applications to manage the response times of the application and closely monitor the performance of Digital Services products. Tasks associated with this work include, but are not limited to:"
        },
        {
          "sourceKey": "mcc-issued-pws-text",
          "locator": "word/document.xml B315; PWS 4.4.1",
          "excerpt": "The Contractor shall analyze and report application performance to MCC management"
        }
      ]
    },
    {
      "number": "5.c",
      "decision": "partial",
      "owner": "Delivery assurance lead",
      "response": "For each ordered new application or significant change, agree a tailored deliverable and acceptance checklist using PWS 4.3.1. The stated documentation set covers system design; test plans, cases, files/data and problem support; development, data migration, integration and implementation plans; operations, administration and training guidance; certification/accreditation and authorization artifacts where applicable; system documentation; configuration requests; version control; lessons learned; bug/enhancement records; legacy-system disposition; and staffing plans. Bind each required item to the delivered source/configuration, selected environment, responsible author and Government acceptance decision. Deliver changed documentation with major and minor releases in the specified electronic formats, including MCC's stated Word/Excel conventions, and write user guidance for a new nontechnical user. Reuse the authoritative delivery records to provide the exact tailored set. For an FFP increment, identify the accepted outcome, interfaces, data migrations, recovery procedure, included documentation and open exceptions in one receiving package.",
      "reviewNote": "RFI 5.c still names Section 5.0; issued PWS 5.0 is Labor Requirements. The actual new-development documentation provisions are in PWS 4.3.1, body elements 287–306. Government task tailoring selects the required set; the RFI cross-reference remains an explicit clarification item.",
      "responseDisposition": "answer",
      "status": "in_progress",
      "issuedEvidence": [
        {
          "sourceKey": "mcc-issued-rfi-text",
          "locator": "word/document.xml B021; RFI question 5.c",
          "excerpt": "The current deliverables are listed in the PWS (Section 5.0). What additional deliverables or changes to the current deliverables would you recommend, particularly in the context of FFP components of the contract?” "
        },
        {
          "sourceKey": "mcc-issued-pws-text",
          "locator": "word/document.xml B287; PWS 4.3.1",
          "excerpt": "All application development activities shall be formally documented. Information System Operation and Maintenance procedures shall likewise be documented. For new applications, deliverables, assumptions, risks, and requirement documentation shall be established and are expected to include, but are not limited to:"
        },
        {
          "sourceKey": "mcc-issued-pws-text",
          "locator": "word/document.xml B288; PWS 4.3.1",
          "excerpt": "\t\tSystem Design"
        },
        {
          "sourceKey": "mcc-issued-pws-text",
          "locator": "word/document.xml B289; PWS 4.3.1",
          "excerpt": "\t\tTest Plan, Determination, Cases, Files/Data, and Problem Support"
        },
        {
          "sourceKey": "mcc-issued-pws-text",
          "locator": "word/document.xml B290; PWS 4.3.1",
          "excerpt": "\t\tDevelopment, Data Migration, Integration, and Implementation Plans"
        },
        {
          "sourceKey": "mcc-issued-pws-text",
          "locator": "word/document.xml B291; PWS 4.3.1",
          "excerpt": "\t\tOperations and Maintenance, Administrative, and Training Documentation"
        },
        {
          "sourceKey": "mcc-issued-pws-text",
          "locator": "word/document.xml B292; PWS 4.3.1",
          "excerpt": "\t\tCertification and Accreditation"
        },
        {
          "sourceKey": "mcc-issued-pws-text",
          "locator": "word/document.xml B293; PWS 4.3.1",
          "excerpt": "\t\tSystem Documentation"
        },
        {
          "sourceKey": "mcc-issued-pws-text",
          "locator": "word/document.xml B294; PWS 4.3.1",
          "excerpt": "\t\tConfiguration Requests"
        },
        {
          "sourceKey": "mcc-issued-pws-text",
          "locator": "word/document.xml B295; PWS 4.3.1",
          "excerpt": "\t\tVersion Control Document"
        },
        {
          "sourceKey": "mcc-issued-pws-text",
          "locator": "word/document.xml B296; PWS 4.3.1",
          "excerpt": "\t\tAuthorization to Operate"
        },
        {
          "sourceKey": "mcc-issued-pws-text",
          "locator": "word/document.xml B297; PWS 4.3.1",
          "excerpt": "\t\tLessons Learned/Retrospective Notes"
        },
        {
          "sourceKey": "mcc-issued-pws-text",
          "locator": "word/document.xml B298; PWS 4.3.1",
          "excerpt": "\t\tBug/Enhancement Requests"
        },
        {
          "sourceKey": "mcc-issued-pws-text",
          "locator": "word/document.xml B299; PWS 4.3.1",
          "excerpt": "\t\tDisposition Plan for any legacy systems being replaced"
        },
        {
          "sourceKey": "mcc-issued-pws-text",
          "locator": "word/document.xml B300; PWS 4.3.1",
          "excerpt": "\t\tStaffing Plan"
        },
        {
          "sourceKey": "mcc-issued-pws-text",
          "locator": "word/document.xml B302; PWS 4.3.1",
          "excerpt": "Required documents shall be identified in the new development task based on project tailoring to ensure a minimum set of documentation is produced that assists with maintenance, governance, and operations."
        },
        {
          "sourceKey": "mcc-issued-pws-text",
          "locator": "word/document.xml B303; PWS 4.3.1",
          "excerpt": "Documentation shall be delivered in electronic form (MCC current standards include both Microsoft Word and Excel), as specified."
        },
        {
          "sourceKey": "mcc-issued-pws-text",
          "locator": "word/document.xml B304; PWS 4.3.1",
          "excerpt": "Documentation that has changed shall be delivered in electronic form (MCC current standards include both Microsoft Word and Excel), as specified through new development tasks, with every major and minor release. User Manuals for an application shall be written with clarity that enables a brand-new user, without a programming or computer background, to understand the details contained therein."
        },
        {
          "sourceKey": "mcc-issued-pws-text",
          "locator": "word/document.xml B320; PWS 5.0",
          "excerpt": "Labor Requirements"
        }
      ]
    },
    {
      "number": "5.d",
      "decision": "partial",
      "owner": "Program lead and solution architect",
      "response": "Start the staffing design with the functions the issued PWS expressly names: a Program Manager responsible for the entirety of contract delivery and performance, and Enterprise and AI Architects or other appropriate labor categories for solutions-architecture support. Map the further functions to the application inventory and workload: product/business analysis, application and platform engineering, service/DevSecOps coordination, security, data engineering, accessibility and specialist platform support. A qualified person may cover compatible functions where capacity and independence permit. Identify each responsibility, delivery output, backup and escalation path before sizing positions. Plan for the PWS's Washington, D.C. Metro expectation for key personnel and Eastern core operating hours. Obtain Section H's actual key-personnel designations and the responding company's qualified, available nominees before presenting a named staffing commitment.",
      "reviewNote": "Issued PWS 4.1.1 names the Program Manager; 4.1.4 names Enterprise and AI Architects or appropriate labor categories; 3.0 gives location/core-hours context; 5.1 points to Section H. These provisions support the staffing design while company qualifications and availability retain their existing review status.",
      "responseDisposition": "answer",
      "status": "in_progress",
      "issuedEvidence": [
        {
          "sourceKey": "mcc-issued-rfi-text",
          "locator": "word/document.xml B022; RFI question 5.d",
          "excerpt": "Can you list the key personnel labor categories you would recommend for a contract of this size and scope?"
        },
        {
          "sourceKey": "mcc-issued-pws-text",
          "locator": "word/document.xml B069; PWS 3.0",
          "excerpt": "Work shall be primarily performed at the Contractor’s office or telework site. Key personnel are expected to be in the Washington, D.C. Metro area. Core hours are generally 9:00 a.m. through 3:00 p.m. Eastern time, Monday through Friday. Contractor personnel are expected to conform to customer Agency normal operating hours for meetings and response times. Government space may be assigned for this support, but the Contractor site or telework site is the anticipated primary place of performance for work under this agreement. If the work being conducted must be completed at MCC or with direct access to the MCC network, equipment will be issued and desk space identified if applicable. Contractor meetings shall be conducted at MCC headquarters located in Washington, D.C., the Contractor’s location, or virtually at the discretion of the Government. The Contractor will be provided access to the MCC network as well as any testing, staging, development, and production environments as needed to complete the work outlined in the PWS. "
        },
